    vec2 px = 1.0 / uRes;
    vec3 n = texture2D(tDiffuse, uv + vec2(px.x, 0.0)).rgb + texture2D(tDiffuse, uv - vec2(px.x, 0.0)).rgb
           + texture2D(tDiffuse, uv + vec2(0.0, px.y)).rgb + texture2D(tDiffuse, uv - vec2(0.0, px.y)).rgb;
    vec3 d = col - n * 0.25;
    col += clamp(d, -0.25, 0.25) * uSharpen;
